const variant=document.body.dataset.variant,view=document.querySelector('#view'),dialog=document.querySelector('#detail');
const frames=[{name:'Ash',have:0,total:4},{name:'Ash Prime',have:2,total:4},{name:'Atlas',have:4,total:4},{name:'Atlas Prime',have:0,total:4},{name:'Banshee',have:0,total:4},{name:'Banshee Prime',have:4,total:4},{name:'Chroma',have:1,total:4},{name:'Equinox',alias:'Эквинокс',have:3,total:9}];
let page='catalog',query='',status='all',selected=frames[7],deficit=false,lastOpener;
const stage=f=>f.have===f.total?'Собран':f.have?'В процессе':'Не начат';
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function details(f){return '<h2 id="detail-title">'+f.name+'</h2><p class="progress-copy">'+stage(f)+' · '+f.have+' / '+f.total+'</p><p class="muted">Обзор компонентов перед подробным рецептом</p>'+ (f.name==='Equinox'?'<div class="component"><strong>Основной чертёж</strong><span>Есть чертёж</span></div><div class="component"><strong>Дневной аспект · 3 части</strong><span>1 / 3</span></div><div class="component"><strong>Ночной аспект · 3 части</strong><span>1 / 3</span></div><p>Нужны оба готовых аспекта. Их части остаются отдельными рецептами.</p>':'<div class="component">Основной чертёж <span>Не получено</span></div><div class="component">Нейрооптика / Шасси / Системы <span>См. прогресс</span></div>')+'<details><summary>Рецепт и источники · пример раскрытия</summary><p>Здесь будут материалы и источники выбранного компонента. Игровые требования в этот макет не включены.</p></details>';}
function draw(){document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.page===page));let out='<div class="intro"><div><h1>'+({catalog:'Коллекция',inventory:'Материалы',summary:'Сводка'})[page]+'</h1><small>'+({catalog:'Найти фрейм и продолжить сбор',inventory:'Найти материал и проверить дефицит',summary:'Разделять прогресс, оценку и расходы'})[page]+'</small></div><span class="progress-copy">Пример: 2 / 8 собрано</span></div>';
if(page==='catalog')out+='<div class="toolbar"><input type="search" aria-label="Найти фрейм" placeholder="Название: Equinox или Эквинокс" value="'+esc(query)+'"><select aria-label="Стадия сбора"><option value="all">Все стадии</option><option value="none">Не начат</option><option value="started">В процессе</option><option value="done">Собран</option></select><button data-reset>Сбросить</button></div><div id="results"></div>';
if(page==='inventory')out+='<div class="toolbar"><input type="search" aria-label="Найти материал" placeholder="Поиск материала" value="'+esc(query)+'"><button data-deficit aria-pressed="'+deficit+'">'+(deficit?'✓ ':'')+'Только дефицит</button><button data-reset>Сбросить</button></div><div id="results"></div>';
if(page==='summary')out+='<div class="warning"><strong>Оценка по устаревшим ценам</strong><br>Данные примера от 10.11.2026. Полнота: 2 / 3 наборов. Свежесть и покрытие — разные показатели.</div><div class="totals"><div class="panel">Осталось купить<strong>≈ 120 пл.</strong><small>Неполная оценка</small></div><div class="panel">Оценка собранного<strong>≈ 60 пл.</strong><small>Не является историей покупок</small></div><div class="panel">Фактические расходы<strong>40 пл.</strong><small>Введено вручную · пример</small></div></div><div class="panel"><div class="component"><strong>Ash Prime</strong><span>В процессе · 2 / 4</span></div><div class="component"><strong>Atlas Prime</strong><span>Не начат · 0 / 4</span></div><div class="component"><strong>Цена Banshee Prime</strong><span>Недоступна · не 0</span></div></div>';
view.innerHTML=out;if(page==='catalog'){view.querySelector('select').value=status;results()}if(page==='inventory')results();}
function results(){const el=document.querySelector('#results');if(page==='catalog'){const list=frames.filter(f=>(f.name+' '+(f.alias||'')).toLowerCase().includes(query.toLowerCase())&&(status==='all'||status==='none'&&!f.have||status==='started'&&f.have>0&&f.have<f.total||status==='done'&&f.have===f.total));el.innerHTML='<p class="result">'+list.length+' из 8 в примере · фильтр: '+({all:'все',none:'не начат',started:'в процессе',done:'собран'})[status]+'</p>'+(list.length?(variant==='b'?'<div class="layout"><div class="frame-list">'+list.map(f=>'<button class="list-item" data-select="'+f.name+'" aria-pressed="'+(selected===f)+'"><strong>'+f.name+'</strong><span>'+stage(f)+' · '+f.have+'/'+f.total+'</span></button>').join('')+'</div><section class="panel" aria-label="Выбранный фрейм">'+details(selected)+'<button data-open="'+selected.name+'">Открыть детали</button></section></div>':'<div class="grid">'+list.map(f=>'<button class="card" data-open="'+f.name+'"><div class="art" aria-hidden="true">'+f.name.slice(0,2).toUpperCase()+'</div><div class="card-copy"><h2>'+f.name+'</h2><span class="badge">'+(f.name.includes('Prime')?'Prime':'Обычный')+'</span><div class="state">'+stage(f)+' · '+f.have+' / '+f.total+'</div><div class="meter"><i style="width:'+f.have/f.total*100+'%"></i></div></div></button>').join('')+'</div>'):'<div class="empty">Нет результатов с текущим запросом и стадией. Измените запрос или нажмите «Сбросить».</div>');}
else {const rows=[['Кредиты',25000,10000],['Форма',1,0],['Сплавы',500,800]].filter(r=>r[0].toLowerCase().includes(query.toLowerCase())&&(!deficit||r[1]>r[2]));el.innerHTML='<p class="result">'+rows.length+' материала в примере · дефицит виден без прокрутки вправо</p><div class="resources">'+rows.map(r=>'<article class="resource"><div><strong>'+r[0]+'</strong></div><div><small>Нужно</small>'+r[1]+'</div><div><small>Есть</small>'+r[2]+'</div><div class="gap"><small>Не хватает</small><strong>'+Math.max(0,r[1]-r[2])+'</strong></div></article>').join('')+'</div>';}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;query='';draw()}if(b.hasAttribute('data-reset')){query='';status='all';deficit=false;draw()}if(b.hasAttribute('data-deficit')){deficit=!deficit;draw()}if(b.dataset.select){selected=frames.find(f=>f.name===b.dataset.select);if(innerWidth<=700)open(selected,b);else results()}if(b.dataset.open)open(frames.find(f=>f.name===b.dataset.open),b);if(b.hasAttribute('data-close'))dialog.close()});
function open(f,b){lastOpener=b;dialog.innerHTML='<button class="close" data-close aria-label="Закрыть">Закрыть</button>'+details(f);dialog.showModal()}dialog.addEventListener('close',()=>lastOpener?.focus());view.addEventListener('input',e=>{if(e.target.type==='search'){query=e.target.value;results()}});view.addEventListener('change',e=>{if(e.target.tagName==='SELECT'){status=e.target.value;results()}});draw();